1	# TikTok content analysis POC (经营计划 P2.0) — 视频概览 + 商品卡
2	# 默认只写 logs/*-debug-*.json，不上报中心 fact（门禁前不建表）。
3	#
4	# Usage:
5	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1
6	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -ConfigPath .\config\stores.config.deal-only.json
7	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -Modules content_overview,product_traffic -ListOnly
8	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -Modules content_probe
9	#   powershell -ExecutionPolicy Bypass -File .\scripts\run-content-poc.ps1 -SkipIngest:$false   # 仍不 dispatch fact；仅当未来加 raw source 时用
10	#
11	# Requires: Ziniao + Bridge. URLs: config.contentUrl / productTrafficUrl（须人工从紫鸟抄实页 path）。
12	
13	param(
14	  [string]$ConfigPath = "",
15	  [switch]$ListOnly,
16	  [string]$DryRun = "",
17	  [string]$Modules = "content_overview,product_traffic",
18	  [switch]$SkipIngest = $true
19	)
20	
21	$ErrorActionPreference = 'Stop'
22	$PSNativeCommandUseErrorActionPreference = $false
23	$root = Split-Path $PSScriptRoot -Parent
24	if (-not $ConfigPath) { $ConfigPath = Join-Path $root 'config\stores.config.json' }
25	if (-not (Test-Path $ConfigPath)) { throw "Missing config: $ConfigPath" }
26	
27	$cfg = Get-Content $ConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
28	$qingquanLib = Join-Path $PSScriptRoot 'qingquan-client.ps1'
29	if (Test-Path $qingquanLib) { . $qingquanLib }
30	
31	$script:logsDir = Join-Path $root 'logs'
32	New-Item -ItemType Directory -Force -Path $script:logsDir | Out-Null
33	$script:runStamp = Get-Date -Format 'yyyyMMdd-HHmmss'
34	$script:runLogFile = Join-Path $script:logsDir ("content-poc-run-{0}.log" -f $script:runStamp)
35	
36	function Write-RunLog([string]$msg) {
37	  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
38	  try { Add-Content -LiteralPath $script:runLogFile -Value $line -Encoding UTF8 } catch { }
39	}
40	function Write-Step([string]$msg) {
41	  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
42	  Write-RunLog $msg
43	}
44	
45	function Write-Utf8File([string]$Path, [string]$Content) {
46	  if ([string]::IsNullOrWhiteSpace($Path)) { throw "Write-Utf8File: Path is empty" }
47	  $dir = Split-Path -Parent $Path
48	  if ($dir -and -not (Test-Path -LiteralPath $dir)) {
49	    New-Item -ItemType Directory -Force -Path $dir | Out-Null
50	  }
51	  $text = if ($null -eq $Content) { '' } else { [string]$Content }
52	  [System.IO.File]::WriteAllText($Path, $text, [System.Text.UTF8Encoding]::new($false))
53	}
54	function ConvertTo-ProcessArgument([string]$s) {
55	  if ($null -eq $s) { return '""' }
56	  if ($s -match '[\s"]') { return '"' + ($s -replace '"', '\"') + '"' }
57	  return $s
58	}
59	function Initialize-ZiniaoCli {
60	  if ($script:ZiniaoNode) { return }
61	  $node = (Get-Command node -ErrorAction SilentlyContinue).Source
62	  if (-not $node) { throw 'node not found' }
63	  $runJs = Join-Path $env:APPDATA 'npm\node_modules\@ziniao-open\cli\scripts\run.js'
64	  if (-not (Test-Path $runJs)) {
65	    $cmd = Get-Command ziniao -ErrorAction SilentlyContinue
66	    if ($cmd) { $runJs = $cmd.Source }
67	  }
68	  if (-not (Test-Path $runJs)) { throw 'ziniao-cli run.js not found' }
69	  $script:ZiniaoNode = $node
70	  $script:ZiniaoRunJs = $runJs
71	}
72	function Invoke-Ziniao([string[]]$CliArgs) {
73	  Initialize-ZiniaoCli
74	  $utf8 = [System.Text.UTF8Encoding]::new($false)
75	  $allArgs = @($script:ZiniaoRunJs) + @($CliArgs)
76	  $argLine = ($allArgs | ForEach-Object { ConvertTo-ProcessArgument ([string]$_) }) -join ' '
77	  $psi = New-Object System.Diagnostics.ProcessStartInfo
78	  $psi.FileName = $script:ZiniaoNode
79	  $psi.Arguments = $argLine
80	  $psi.UseShellExecute = $false
81	  $psi.RedirectStandardOutput = $true
82	  $psi.RedirectStandardError = $true
83	  $psi.CreateNoWindow = $true
84	  $psi.StandardOutputEncoding = $utf8
85	  $psi.StandardErrorEncoding = $utf8
86	  $p = New-Object System.Diagnostics.Process
87	  $p.StartInfo = $psi
88	  [void]$p.Start()
89	  $stdout = $p.StandardOutput.ReadToEnd()
90	  $stderr = $p.StandardError.ReadToEnd()
91	  $p.WaitForExit()
92	  if ($stderr) { Write-Host $stderr }
93	  return $stdout
94	}
95	function ConvertTo-ScrapeOneLine([string]$js) {
96	  return (($js -replace '(?m)^\s*//.*$', '' -replace '\r?\n', ' ' -replace '\s+', ' ').Trim())
97	}
98	function Get-ScrapePayload([string]$execOut) {
99	  if ([string]::IsNullOrWhiteSpace($execOut)) { return $null }
100	  try {
101	    $j = $execOut | ConvertFrom-Json
102	    if ($j.data -and $j.data.data -and $j.data.data.result) {
103	      return ([string]$j.data.data.result | ConvertFrom-Json)
104	    }
105	    if ($null -ne $j.ok) { return $j }
106	  } catch { }
107	  $m = [regex]::Matches($execOut, '\{(?:[^{}]|(?<o>\{)|(?<-o>\}))+(?(o)(?!))\}')
108	  if ($m.Count -gt 0) {
109	    try { return ($m[$m.Count - 1].Value | ConvertFrom-Json) } catch { }
110	  }
111	  return $null
112	}
113	function Convert-DryRunFlag([string]$raw) {
114	  if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
115	  switch -Regex ($raw.Trim()) {
116	    '^(?i:true|1|yes|y|\$true)$'  { return $true }
117	    '^(?i:false|0|no|n|\$false)$' { return $false }
118	    default { throw "Invalid -DryRun '$raw'" }
119	  }
120	}
121	function Get-DisplayName($store, $map) {
122	  $n = [string]$store.storeName
123	  if ($map -and $map.PSObject.Properties.Name -contains $n) { return [string]$map.$n }
124	  return $n
125	}
126	function Get-ModuleUrl($store, $cfg, $moduleKey) {
127	  $plat = ''
128	  if ($store.platformName) { $plat = [string]$store.platformName }
129	  elseif ($store.platform) { $plat = [string]$store.platform }
130	  $mapKey = switch ($moduleKey) {
131	    'content_overview' { 'contentUrl' }
132	    'product_traffic' { 'productTrafficUrl' }
133	    'content_probe' { 'contentUrl' }
134	    'content_nav_discover' { 'contentNavStartUrl' }
135	    default { $null }
136	  }
137	  # 2026-08-04 实勘默认（Deal UK）；content-analysis/* 会回 data-overview
138	  $defaults = @{
139	    content_overview     = 'https://seller-uk.tiktok.com/compass/video-analytics?shop_region=GB'
140	    product_traffic      = 'https://seller-uk.tiktok.com/compass/product-card-analytics?shop_region=GB'
141	    content_probe        = 'https://seller-uk.tiktok.com/compass/video-analytics?shop_region=GB'
142	    content_nav_discover = 'https://seller-uk.tiktok.com/homepage'
143	  }
144	  if ($mapKey -and $cfg.$mapKey) {
145	    $block = $cfg.$mapKey
146	    if ($block.byPlatform -and $plat) {
147	      foreach ($p in $block.byPlatform.PSObject.Properties) {
148	        if ($plat -eq [string]$p.Name -or $plat -like ("*{0}*" -f $p.Name)) { return [string]$p.Value }
149	      }
150	    }
151	    if ($block.default) { return [string]$block.default }
152	  }
153	  if ($cfg.urls -and $cfg.urls.$moduleKey) { return [string]$cfg.urls.$moduleKey }
154	  if ($moduleKey -eq 'content_nav_discover') {
155	    # 从首页或 data-overview 扫导航，比猜 content-analysis path 稳
156	    if ($cfg.shopDailyUrl -and $cfg.shopDailyUrl.default) { return [string]$cfg.shopDailyUrl.default }
157	    return 'https://seller-uk.tiktok.com/homepage'
158	  }
159	  return [string]$defaults[$moduleKey]
160	}
161	
162	$modList = @($Modules.Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
163	$scriptMap = @{
164	  content_overview     = (Join-Path $root 'scripts\scrape-content-overview-page.js')
165	  product_traffic      = (Join-Path $root 'scripts\scrape-product-traffic-page.js')
166	  content_probe        = (Join-Path $root 'scripts\_probe-content-page.js')
167	  content_nav_discover = (Join-Path $root 'scripts\_discover-content-nav.js')
168	}
169	foreach ($m in $modList) {
170	  if (-not $scriptMap.ContainsKey($m)) { throw "Unknown module: $m (use content_overview,product_traffic,content_probe,content_nav_discover)" }
171	  if (-not (Test-Path $scriptMap[$m])) { throw "Missing scrape script: $($scriptMap[$m])" }
172	}
173	
174	Write-Step '===== content-poc multi-store START (P2.0 gate) ====='
175	Write-Step ("config={0} modules={1} SkipIngest={2}" -f $ConfigPath, ($modList -join ','), [bool]$SkipIngest)
176	Write-Step 'NOTE: POC does not create PG fact tables. Debug JSON only unless you opt into raw dump.'
177	Initialize-ZiniaoCli
178	$listOut = Invoke-Ziniao @('store', 'list')
179	$storesObj = $listOut | ConvertFrom-Json
180	$all = @()
181	if ($storesObj.data) {
182	  if ($storesObj.data.items) { $all = @($storesObj.data.items) }
183	  elseif ($storesObj.data -is [System.Array]) { $all = @($storesObj.data) }
184	  elseif ($storesObj.data.list) { $all = @($storesObj.data.list) }
185	  elseif ($storesObj.data.stores) { $all = @($storesObj.data.stores) }
186	}
187	$norm = @()
188	foreach ($s in $all) {
189	  $sid = ''; if ($s.storeId) { $sid = [string]$s.storeId } elseif ($s.id) { $sid = [string]$s.id }
190	  $sname = ''; if ($s.storeName) { $sname = [string]$s.storeName } elseif ($s.name) { $sname = [string]$s.name }
191	  $plat = ''; if ($s.platformName) { $plat = [string]$s.platformName } elseif ($s.platform) { $plat = [string]$s.platform }
192	  if (-not $sid) { continue }
193	  $norm += [pscustomobject]@{
194	    storeId = $sid; storeName = $sname; platform = $plat; platformName = $plat
195	    ip = $(if ($s.ip) { [string]$s.ip } else { '' })
196	  }
197	}
198	$selected = @($norm)
199	if ($cfg.filter) {
200	  if ($cfg.filter.platformContains -and @($cfg.filter.platformContains).Count -gt 0) {
201	    $selected = @($selected | Where-Object {
202	      $p = $_.platform; $ok = $false
203	      foreach ($k in @($cfg.filter.platformContains)) { if ($p -like ("*{0}*" -f $k)) { $ok = $true } }
204	      $ok
205	    })
206	  }
207	  if ($cfg.filter.requireIp) {
208	    $selected = @($selected | Where-Object { -not [string]::IsNullOrWhiteSpace($_.ip) })
209	  }
210	  if ($cfg.filter.excludeStoreIds) {
211	    $ex = @($cfg.filter.excludeStoreIds | ForEach-Object { [string]$_ })
212	    $selected = @($selected | Where-Object { $ex -notcontains $_.storeId })
213	  }
214	  if ($cfg.filter.includeStoreIds -and @($cfg.filter.includeStoreIds).Count -gt 0) {
215	    $inc = @($cfg.filter.includeStoreIds | ForEach-Object { [string]$_ })
216	    $selected = @($selected | Where-Object { $inc -contains $_.storeId })
217	  }
218	}
219	
220	# 与 shop-modules 相同：欧盟 Pop 等 opsExclude
221	if ($cfg.modules) {
222	  $oex = @()
223	  if ($cfg.modules.opsExcludeStoreIds) { $oex += @($cfg.modules.opsExcludeStoreIds | ForEach-Object { [string]$_ }) }
224	  if ($cfg.modules.ordersExcludeStoreIds) { $oex += @($cfg.modules.ordersExcludeStoreIds | ForEach-Object { [string]$_ }) }
225	  $oex = @($oex | Select-Object -Unique | Where-Object { $_ })
226	  if ($oex.Count -gt 0) {
227	    $before = $selected.Count
228	    $selected = @($selected | Where-Object { $oex -notcontains $_.storeId })
229	    if ($before -ne $selected.Count) {
230	      Write-Step ("opsExcludeStoreIds removed {0} store(s)" -f ($before - $selected.Count))
231	    }
232	  }
233	  $pex = @()
234	  if ($cfg.modules.opsExcludePlatformContains) { $pex += @($cfg.modules.opsExcludePlatformContains | ForEach-Object { [string]$_ }) }
235	  if ($cfg.modules.ordersExcludePlatformContains) { $pex += @($cfg.modules.ordersExcludePlatformContains | ForEach-Object { [string]$_ }) }
236	  $pex = @($pex | Select-Object -Unique | Where-Object { $_ })
237	  if ($pex.Count -gt 0) {
238	    $before = $selected.Count
239	    $selected = @($selected | Where-Object {
240	      $p = [string]$_.platform
241	      $hit = $false
242	      foreach ($k in $pex) { if ($k -and $p -like ("*{0}*" -f $k)) { $hit = $true } }
243	      -not $hit
244	    })
245	    if ($before -ne $selected.Count) {
246	      Write-Step ("opsExcludePlatformContains removed {0} store(s)" -f ($before - $selected.Count))
247	    }
248	  }
249	}
250	
251	Write-Step ("stores selected: {0}" -f $selected.Count)
252	foreach ($s in $selected) { Write-Step ("  - {0} | {1} | {2}" -f $s.storeId, $s.storeName, $s.platform) }
253	if ($ListOnly) { Write-Step 'ListOnly done'; return }
254	if ($selected.Count -eq 0) { throw 'No stores matched' }
255	
256	$dryParsed = Convert-DryRunFlag $DryRun
257	$useDryRun = if ($null -ne $dryParsed) { [bool]$dryParsed } else {
258	  if ($cfg.options -and $null -ne $cfg.options.dryRun) { [bool]$cfg.options.dryRun } else { $true }
259	}
260	$waitOpen = 28000; $waitVisit = 35000; $retries = 3
261	if ($cfg.options.waitAfterOpenMs) { $waitOpen = [Math]::Max(15000, [int]$cfg.options.waitAfterOpenMs) }
262	if ($cfg.options.waitAfterVisitMs) { $waitVisit = [Math]::Max(15000, [int]$cfg.options.waitAfterVisitMs) }
263	if ($cfg.options.scrapeRetries) { $retries = [Math]::Max(2, [int]$cfg.options.scrapeRetries) }
264	
265	$bizDate = (Get-Date).Date.AddDays(-1).ToString('yyyy-MM-dd')
266	if ($cfg.options -and $cfg.options.dateMode -eq 'today') {
267	  $bizDate = (Get-Date).Date.ToString('yyyy-MM-dd')
268	}
269	Write-Step ("dryRun={0} biz_date={1} (content page window may still be 近N天 — see payload.window)" -f $useDryRun, $bizDate)
270	
271	$oneLiners = @{}
272	foreach ($m in $modList) {
273	  $oneLiners[$m] = ConvertTo-ScrapeOneLine (Get-Content $scriptMap[$m] -Raw -Encoding UTF8)
274	}
275	
276	$summary = @()
277	foreach ($store in $selected) {
278	  $sid = $store.storeId
279	  $sname = $store.storeName
280	  $display = Get-DisplayName $store $cfg.storeNameMap
281	  Write-Step ("==== STORE {0} ({1}) => {2} ====" -f $sname, $sid, $display)
282	
283	  $firstUrl = Get-ModuleUrl $store $cfg $modList[0]
284	  try {
285	    Write-Step '  open store...'
286	    $openArgs = @('store', 'open', '--id', $sid, '--url', $firstUrl)
287	    if ($cfg.options.windowRatio -and $cfg.options.windowRatio -ne 'none') {
288	      $openArgs += @('--window-ratio', [string]$cfg.options.windowRatio)
289	    }
290	    Write-Host (Invoke-Ziniao $openArgs)
291	    Start-Sleep -Milliseconds $waitOpen
292	
293	    foreach ($mod in $modList) {
294	      $item = [ordered]@{
295	        storeId = $sid; storeName = $sname; displayName = $display; module = $mod
296	        ok = $false; url = $null; error = $null; debugPath = $null
297	      }
298	      $modUrl = Get-ModuleUrl $store $cfg $mod
299	      $item.url = $modUrl
300	      Write-Step ("  -- module {0} url={1}" -f $mod, $modUrl)
301	      try {
302	        $null = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $modUrl, '--wait-until', 'load', '--timeout', '120000')
303	        # content SPA often slower than homepage
304	        $extraWait = [Math]::Max(40000, $waitVisit)
305	        Start-Sleep -Milliseconds $extraWait
306	        $payload = $null
307	        $lastErr = $null
308	        for ($attempt = 1; $attempt -le $retries; $attempt++) {
309	          Write-Step ("  scrape {0} attempt {1}/{2}..." -f $mod, $attempt, $retries)
310	          $execOut = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $oneLiners[$mod], '--timeout', '60000')
311	          if ([string]::IsNullOrWhiteSpace($execOut)) {
312	            $lastErr = 'empty page exec'
313	          } else {
314	            $payload = Get-ScrapePayload $execOut
315	            $payloadUrl = ''
316	            if ($payload -and $payload.url) { $payloadUrl = [string]$payload.url }
317	            # store reuse / Bridge 抖动时偶发 about:blank，强制 revisit
318	            if ($payloadUrl -match 'about:blank' -or $lastErr -match 'about:blank') {
319	              $lastErr = 'page is about:blank — revisit'
320	              $payload = $null
321	            } elseif ($payload -and $payload.ok) {
322	              $lastErr = $null
323	              break
324	            } else {
325	              $lastErr = $null
326	              if ($payload -and $payload.error) { $lastErr = [string]$payload.error }
327	              else { $lastErr = 'scrape fail' }
328	            }
329	            try {
330	              $rawPath = Join-Path $script:logsDir ("{0}-exec-raw-{1}-a{2}.txt" -f $mod, $sid, $attempt)
331	              Write-Utf8File -Path $rawPath -Content ([string]$execOut)
332	            } catch { Write-Step ("  warn write exec-raw: {0}" -f $_) }
333	          }
334	          Write-Step ("  attempt fail: {0}" -f $lastErr)
335	          if ($attempt -lt $retries) {
336	            Start-Sleep -Seconds 12
337	            if ($lastErr -match 'about:blank') {
338	              Write-Step '  reopen visit after about:blank'
339	              $null = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $modUrl, '--wait-until', 'load', '--timeout', '120000')
340	              Start-Sleep -Seconds 35
341	            } elseif ($lastErr -match 'SPA not ready|not ready|no content|no product') {
342	              Write-Step '  extra 30s for content SPA render'
343	              Start-Sleep -Seconds 30
344	            } else {
345	              $null = Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $modUrl, '--wait-until', 'load', '--timeout', '120000')
346	              Start-Sleep -Seconds 20
347	            }
348	          }
349	        }
350	
351	        # 即使 ok=false 也落 debug，便于改 URL/选择器
352	        $dbg = Join-Path $script:logsDir ("{0}-debug-{1}-{2}.json" -f $mod, $sid, $script:runStamp)
353	        $dbgObj = @{
354	          storeId = $sid
355	          displayName = $display
356	          url = $modUrl
357	          bizDate = $bizDate
358	          module = $mod
359	          scrapeOk = [bool]($payload -and $payload.ok)
360	          payload = $payload
361	          lastError = $lastErr
362	        }
363	        try {
364	          $json = $dbgObj | ConvertTo-Json -Depth 12 -Compress:$false
365	          Write-Utf8File -Path $dbg -Content $json
366	          $item.debugPath = $dbg
367	          Write-Step ("  debug: {0}" -f $dbg)
368	        } catch {
369	          Write-Step ("  warn write debug: {0}" -f $_)
370	        }
371	
372	        if ($lastErr -or -not $payload -or -not $payload.ok) {
373	          if ($lastErr) { throw $lastErr }
374	          throw 'no payload'
375	        }
376	
377	        if (-not $SkipIngest) {
378	          Write-Step '  SkipIngest=false but POC has no fact source registered — skip center ingest (by design)'
379	        } else {
380	          Write-Step '  skip qingquan (POC default SkipIngest)'
381	        }
382	        $item.ok = $true
383	      } catch {
384	        $item.error = [string]$_
385	        Write-Step ("  FAIL {0}: {1}" -f $mod, $item.error)
386	      }
387	      $summary += [pscustomobject]$item
388	    }
389	  } catch {
390	    Write-Step ("  STORE FAIL {0}: {1}" -f $sname, $_)
391	  } finally {
392	    if ($cfg.options -and $null -ne $cfg.options.closeAfter -and -not [bool]$cfg.options.closeAfter) {
393	      Write-Step '  leave store open'
394	    } else {
395	      try { $null = Invoke-Ziniao @('store', 'close', '--id', $sid) } catch { }
396	    }
397	  }
398	  if ($cfg.options.delayBetweenStoresMs) { Start-Sleep -Milliseconds ([int]$cfg.options.delayBetweenStoresMs) }
399	}
400	
401	Write-Step '======== CONTENT-POC SUMMARY ========'
402	$summary | Format-Table storeName, module, ok, error -AutoSize
403	$okN = @($summary | Where-Object { $_.ok }).Count
404	Write-Step ("OK {0}/{1}" -f $okN, $summary.Count)
405	$sumPath = Join-Path $script:logsDir ("content-poc-summary-{0}.json" -f $script:runStamp)
406	Write-Utf8File -Path $sumPath -Content (($summary | ConvertTo-Json -Depth 6))
407	Write-Step ("summary: {0}" -f $sumPath)
408	Write-Step 'Next: fill docs/TK-P2-内容分析POC结论.md from debug JSON; do NOT create empty fact tables until gate passes.'
409	Write-Step '===== content-poc multi-store END ====='
