532	function Send-QingquanIngest {
533	  param(
534	    [Parameter(Mandatory = $true)] $Config,
535	    [Parameter(Mandatory = $true)] $Items,
536	    [string]$Source = '',
537	    [switch]$Quiet
538	  )
539	  $q = Get-QingquanConfig $Config
540	  if (-not $q.enabled) {
541	    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'qingquan.disabled'; accepted = 0; duplicated = 0; failed = 0 }
542	  }
543	  if (-not $q.apiKey) {
544	    $msg = 'qingquan.apiKey empty'
545	    if ($q.failOpen) {
546	      if (-not $Quiet) { Write-Warning $msg }
547	      return [pscustomobject]@{ ok = $false; skipped = $false; error = $msg; accepted = 0; duplicated = 0; failed = 0 }
548	    }
549	    throw $msg
550	  }
551	
552	  $itemList = Get-QingquanItemList $Items
553	  if ($itemList.Count -eq 0) {
554	    return [pscustomobject]@{ ok = $true; skipped = $true; reason = 'empty-items'; accepted = 0; duplicated = 0; failed = 0 }
555	  }
556	
557	  # 大批量（订单 400 行 refresh）单请求易超时；按批发送并汇总
558	  $batchSize = 80
559	  if ($itemList.Count -gt 120) { $batchSize = 50 }
560	  $chunks = New-Object System.Collections.ArrayList
561	  for ($i = 0; $i -lt $itemList.Count; $i += $batchSize) {
562	    $end = [Math]::Min($i + $batchSize - 1, $itemList.Count - 1)
563	    $chunk = New-Object System.Collections.ArrayList
564	    for ($j = $i; $j -le $end; $j++) { [void]$chunk.Add($itemList[$j]) }
565	    # 关键：不要把单元素 ArrayList 直接当 $Items 传——PS 会解包成 Hashtable，
566	    # Get-QingquanItemList 再按字典 key 枚举 → 0 items → 假成功 accepted=0
567	    [void]$chunks.Add(@($chunk.ToArray()))
568	  }
569	
570	  $totAccepted = 0; $totDup = 0; $totFailed = 0; $lastErr = $null; $anyOk = $false
571	  $idx = 0
572	  foreach ($chunk in $chunks) {
573	    $idx++
574	    $n = @($chunk).Count
575	    if ($chunks.Count -gt 1 -and -not $Quiet) {
576	      Write-Host ("  qingquan batch {0}/{1} items={2}" -f $idx, $chunks.Count, $n)
577	    }
578	    $one = Send-QingquanIngestBatch -Config $Config -Items $chunk -Source $Source -Quiet:$Quiet -TimeoutSecOverride $(if ($n -gt 40) { 90 } else { 0 })
579	    if ($one.ok) { $anyOk = $true }
580	    $totAccepted += [int]$one.accepted
581	    $totDup += [int]$one.duplicated
582	    $totFailed += [int]$one.failed
583	    if ($one.error) { $lastErr = [string]$one.error }
584	  }
585	  return [pscustomobject]@{
586	    ok = $anyOk -or ($totFailed -eq 0)
587	    skipped = $false
588	    accepted = $totAccepted
589	    duplicated = $totDup
590	    failed = $totFailed
591	    error = $lastErr
592	  }
593	}
